	  CASE_mul_fState_S4D_OUT_BITS_36_TO_34_0_CASE__ETC__q16 =
	      (mul_fState_S4$D_OUT[1:0] == 2'b0) ?
		mul_fState_S4$D_OUT[33:2] :
		{ (mul_fState_S4$D_OUT[1:0] == 2'b01 ||
		   mul_fState_S4$D_OUT[1:0] == 2'b10 ||
		   mul_fState_S4$D_OUT[1:0] == 2'b11) &&
		  mul_fState_S4$D_OUT[33],
		  CASE_mul_fState_S4D_OUT_BITS_1_TO_0_0_0_0b1_I_ETC__q15 };
      default: CASE_mul_fState_S4D_OUT_BITS_36_TO_34_0_CASE__ETC__q16 =
		   { CASE_mul_fState_S4D_OUT_BITS_36_TO_34_2_mul_f_ETC__q11,
		     CASE_mul_fState_S4D_OUT_BITS_36_TO_34_2_IF_mu_ETC__q12 };
    endcase
  end

  // handling of inlined registers

  always@(posedge CLK)
  begin
    if (RST_N == `BSV_RESET_VALUE)
      begin
        rgA <= `BSV_ASSIGNMENT_DELAY 32'd0;
	rgB <= `BSV_ASSIGNMENT_DELAY 32'd0;
	rgBusy <= `BSV_ASSIGNMENT_DELAY 1'd0;
	rgC <= `BSV_ASSIGNMENT_DELAY 32'd0;
	rgDone <= `BSV_ASSIGNMENT_DELAY 1'd0;
	rgEX <= `BSV_ASSIGNMENT_DELAY 5'd0;
	rgRM <= `BSV_ASSIGNMENT_DELAY 3'd0;
      end
    else
      begin
        if (rgA$EN) rgA <= `BSV_ASSIGNMENT_DELAY rgA$D_IN;
	if (rgB$EN) rgB <= `BSV_ASSIGNMENT_DELAY rgB$D_IN;
	if (rgBusy$EN) rgBusy <= `BSV_ASSIGNMENT_DELAY rgBusy$D_IN;
	if (rgC$EN) rgC <= `BSV_ASSIGNMENT_DELAY rgC$D_IN;
	if (rgDone$EN) rgDone <= `BSV_ASSIGNMENT_DELAY rgDone$D_IN;
	if (rgEX$EN) rgEX <= `BSV_ASSIGNMENT_DELAY rgEX$D_IN;
	if (rgRM$EN) rgRM <= `BSV_ASSIGNMENT_DELAY rgRM$D_IN;
      end
  end

  // synopsys translate_off
  `ifdef BSV_NO_INITIAL_BLOCKS
  `else // not BSV_NO_INITIAL_BLOCKS
  initial
  begin
    rgA = 32'hAAAAAAAA;
    rgB = 32'hAAAAAAAA;
    rgBusy = 1'h0;
    rgC = 32'hAAAAAAAA;
    rgDone = 1'h0;
    rgEX = 5'h0A;
    rgRM = 3'h2;
  end
  `endif // BSV_NO_INITIAL_BLOCKS
  // synopsys translate_on
endmodule  // mkFp32MulCore

